import type { Metadata } from "next";
import { site } from "@/content/site";

/** The site-wide social image generated by app/opengraph-image.tsx. */
export const OG_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${site.name} ${site.year} — ${site.institute}`,
} as const;

type SectionMetadataInput = {
  /** Section name, e.g. "Events". */
  title: string;
  description: string;
  /** Route path, e.g. "/events". */
  path: string;
};

/**
 * Per-route metadata for section pages. A child `openGraph` / `twitter` object
 * replaces the root one instead of merging (including the file-based
 * opengraph-image), so the shared fields and the image are repeated here.
 */
export function sectionMetadata({ title, description, path }: SectionMetadataInput): Metadata {
  const shareTitle = `${title} · ${site.name} ${site.year}`;
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: site.name,
      title: shareTitle,
      description,
      url: path,
      images: [OG_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title: shareTitle,
      description,
      images: [OG_IMAGE],
    },
  };
}
